  "groups": [
    {
      "all_of": [
        {
          "condition": "yearly safety audit count >= 40",
          "item": "e_0079ce"
        },
        {
          "condition": "annual compliance score >= 80",
          "item": "e_00508f"
        }
      ]
    },
    {
      "all_of": [
        {
          "condition": "Joint Commission accreditation",
          "item": "e_00cad3"
        }
      ]
    }
  ]
}
```

